    if (!st) {
        st = { places: {}, itinerary: [], view: null, edges: {} }
        flow.set('rankState', st)
    }
    return st
}
function save(st) { flow.set('rankState', st) }
function uid() { return (Date.now().toString(36) + Math.random().toString(36).slice(2, 7)) }

let st = getState()
const p = msg.payload || {}
const action = (msg.action != null ? msg.action : p.action)
const data = p.data || {}
const normalizeCurrency = value => {
    const currency = String(value || '').trim().toUpperCase()
    return /^[A-Z]{3}$/.test(currency) ? currency : null
}
const normalizeCurrencies = values => {
    const currencies = (Array.isArray(values) ? values : []).map(normalizeCurrency).filter(Boolean)
    const unique = [...new Set(currencies)]
    return unique.length ? unique : ['CHF']
}
const normalizeRelativePeriod = value => {
    const normalized = String(value || '').toUpperCase().replace(/\s+/g, '')
    const match = /^J([1-9]\d*)([MAS])?(?:-J?([1-9]\d*)([MAS])?)?$/.exec(normalized)
    const startDay = Number(match?.[1]), endDay = Number(match?.[3] || match?.[1])
    if (!match || endDay < startDay) return ''
    const start = `J${startDay}${match[2] || ''}`
    if (endDay === startDay && !match[4]) return start
    return `${start}-J${endDay}${match[4] || ''}`
}
st.budgetCurrencies = normalizeCurrencies(st.budgetCurrencies)
st.startPlaceId = st.itinerary.includes(st.startPlaceId) ? st.startPlaceId : (st.itinerary[0] || '')

try {
    switch (action) {
        case 'requestState': {
            break
        }
        case 'setView': {
            st.view = (data && data.center) ? { center: data.center } : null
            break
        }
        case 'setPeople': {
            st.people = Math.max(1, parseInt(data.people, 10) || 2)
            break
        }
        case 'setTripNotes': {
            st.notes = String(data.notes || '').slice(0, 20000)
            break
        }
        case 'setBudgetCurrencies': {
            st.budgetCurrencies = normalizeCurrencies(data.currencies)
            const defaultCurrency = st.budgetCurrencies[0]
            for (const place of Object.values(st.places || {})) {
                const currency = normalizeCurrency(place?.budgetCurrency) || defaultCurrency
                place.budgetCurrency = st.budgetCurrencies.includes(currency) ? currency : defaultCurrency
            }
            break
        }
        case 'addPlace': {
            const requestedCurrency = normalizeCurrency(data.budgetCurrency)
            const budgetCurrency = requestedCurrency || st.budgetCurrencies[0]
            if (!st.budgetCurrencies.includes(budgetCurrency)) st.budgetCurrencies.push(budgetCurrency)
            const id = uid()
            st.places[id] = {
                id,
                name: String(data.name || 'Lieu').slice(0, 160),
                lat: Number(data.lat),
                lng: Number(data.lng),
                durationH: Number(data.durationH) || 0,
                budget: Math.max(0, Number(data.budget) || 0),
                budgetFree: data.budgetFree === true,
                budgetCurrency,
                budgetScope: data.budgetScope === 'group' ? 'group' : 'individual',
                desc: String(data.desc || '').slice(0, 2000),
                closedDays: Array.isArray(data.closedDays) ? data.closedDays.map(Number) : [],
                ratings: {},
                tags: Array.isArray(data.tags) ? data.tags.map(String) : [],
                image: (typeof data.image === 'string') ? data.image : '',
                optionGroup: (typeof data.optionGroup === 'string') ? data.optionGroup : '',
                relativePeriod: normalizeRelativePeriod(data.relativePeriod),
                url: (typeof data.url === 'string') ? data.url : ''
            }
            const u = (msg && msg.payload && msg.payload.user) ? String(msg.payload.user) : null
            if (u && (data.rating != null)) {
                const r = Math.max(1, Math.min(6, Number(data.rating) || 0))
                if (r) st.places[id].ratings[u] = r
            }
            st.itinerary.push(id)
            if (!st.startPlaceId) st.startPlaceId = id
            break
        }
        case 'removePlace': {
            const id = data.id
            if (st.places[id]) {
                delete st.places[id]
                st.itinerary = st.itinerary.filter(x => x !== id)
                if (st.startPlaceId === id) st.startPlaceId = st.itinerary[0] || ''
            }
            break
        }
        case 'reorder': {
            const arr = Array.isArray(data.itinerary) ? data.itinerary : []
            st.itinerary = arr.filter(id => st.places[id])
            if (st.itinerary.includes(data.startPlaceId)) st.startPlaceId = data.startPlaceId
            if (!st.itinerary.includes(st.startPlaceId)) st.startPlaceId = st.itinerary[0] || ''
            break
        }
        case 'updatePlace': {
            const id = data.id
            const patch = data.patch || {}
            const t = st.places[id]
            if (t) {
                const clean = { ...patch }
                if ('budget' in clean) clean.budget = Math.max(0, Number(clean.budget) || 0)
                if ('budgetFree' in clean) clean.budgetFree = clean.budgetFree === true
                if ('budgetCurrency' in clean) {
                    clean.budgetCurrency = normalizeCurrency(clean.budgetCurrency) || st.budgetCurrencies[0]
                    if (!st.budgetCurrencies.includes(clean.budgetCurrency)) st.budgetCurrencies.push(clean.budgetCurrency)
                }
                if ('budgetScope' in clean) clean.budgetScope = clean.budgetScope === 'group' ? 'group' : 'individual'
                if ('relativePeriod' in clean) clean.relativePeriod = normalizeRelativePeriod(clean.relativePeriod)
                Object.assign(t, clean)
            }
            break
        }
        case 'ratePlace': {
            const id = data.id
            const r = Math.max(1, Math.min(6, Number(data.rating) || 0))
            const u = (msg && msg.payload && msg.payload.user) ? String(msg.payload.user) : null
            if (st.places[id] && u && r) {
                st.places[id].ratings = st.places[id].ratings || {}
                st.places[id].ratings[u] = r
            }
            break
        }
        case 'setEdge': {
            const from = data.from, to = data.to
            if (!st.edges) st.edges = {}
            const k = `${from}|${to}`
            st.edges[k] = st.edges[k] || {}
            if ('realKm' in data) st.edges[k].realKm = (data.realKm == null ? null : Number(data.realKm))
            if ('realMin' in data) st.edges[k].realMin = (data.realMin == null ? null : Number(data.realMin))
            break
        }
        default: {
            // no-op
        }
    }
    save(st)
} catch (e) {
    node.warn(e)
}

return { payload: { state: st } }

