const REG_FILE = "/home/pi/trips/trips.json";
const BASE_DIR = "/home/pi/trips";
const DEFAULT_FILE = "/home/pi/trips/trip-planner.yaml";

function normReg(reg) {
    if (!reg || typeof reg !== 'object') reg = {};
    if (!Array.isArray(reg.trips)) reg.trips = [];
    if (!Array.isArray(reg.ignored)) reg.ignored = [];
    if (!reg.trips.some(t => t && t.id === 'default')) {
        reg.trips.unshift({ id: "default", name: "Voyage principal", file: DEFAULT_FILE });
    }
    if (!reg.active || !reg.trips.some(t => t && t.id === reg.active)) reg.active = reg.trips[0].id;
    return reg;
}

function slug(s) {
    return String(s || '').toLowerCase().normalize('NFD')
        .replace(/\p{Diacritic}/gu, '')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .slice(0, 40) || 'trip';
}

function fileFor(id) {
    if (id === "default") return DEFAULT_FILE;
    return BASE_DIR + '/' + id + '.yaml';
}

function inferredName(id) {
    const label = String(id || 'Voyage')
        .replace(/-[a-z0-9]{4}$/i, '')
        .replace(/[-_]+/g, ' ')
        .trim();
    return label.charAt(0).toUpperCase() + label.slice(1);
}

function discoverYaml(reg) {
    let changed = false;
    fs.mkdirSync(BASE_DIR, { recursive: true });
    const files = fs.readdirSync(BASE_DIR, { withFileTypes: true })
        .filter(entry => entry.isFile() && /\.ya?ml$/i.test(entry.name))
        .map(entry => entry.name)
        .sort((a, b) => a.localeCompare(b, 'fr'));

    for (const filename of files) {
        const isDefault = filename === 'trip-planner.yaml';
        const id = isDefault ? 'default' : filename.replace(/\.ya?ml$/i, '');
        if (reg.ignored.includes(id)) continue;
        const file = BASE_DIR + '/' + filename;
        const existing = reg.trips.find(trip => trip && trip.id === id);
        if (!existing) {
            reg.trips.push({ id, name: isDefault ? 'Voyage principal' : inferredName(id), file });
            changed = true;
        } else if (existing.file !== file) {
            existing.file = file;
            changed = true;
        }
    }

    reg.trips.sort((a, b) => {
        if (a.id === 'default') return -1;
        if (b.id === 'default') return 1;
        return String(a.name || a.id).localeCompare(String(b.name || b.id), 'fr');
    });
    return changed;
}

function activeFile(reg) {
    const trip = reg.trips.find(item => item && item.id === reg.active);
    return (trip && trip.file) || fileFor(reg.active);
}

let reg = normReg(flow.get('tripRegistry'));
const p = msg.payload || {};
const action = p.action;
const data = p.data || {};
const hadRegistry = flow.get('tripRegistry') != null;
const discovered = discoverYaml(reg);
let writeMsg = null;
let uiMsg = { payload: {} };

function fillUi() {
    uiMsg.payload.trips = reg.trips.map(trip => ({
        id: trip.id,
        name: trip.name,
        file: trip.file || fileFor(trip.id)
    }));
    uiMsg.payload.activeTripId = reg.active;
    uiMsg.payload.activeTripFile = activeFile(reg);
    uiMsg.payload.storagePath = BASE_DIR;
}

function persistContext() {
    flow.set('tripRegistry', reg);
    flow.set('activeTripId', reg.active);
    flow.set('activeTripFile', activeFile(reg));
}

if (action === "listTrips") {
    persistContext();
    fillUi();
    uiMsg._needReload = (flow.get('loadedOnce') !== true);
    const forceSave = data && (data.forceSave === true || data.rescan === true);
    if (!hadRegistry || forceSave || discovered) {
        writeMsg = { filename: REG_FILE, payload: JSON.stringify(reg, null, 2) };
    }
    return [writeMsg, uiMsg];
}

if (action === "createTrip") {
    const name = (data.name || "Nouveau voyage").trim();
    const id = slug(name) + '-' + Date.now().toString(36).slice(-4);
    reg.ignored = reg.ignored.filter(value => value !== id);
    reg.trips.push({ id, name, file: fileFor(id) });
    reg.active = id;
}

if (action === "renameTrip") {
    const trip = reg.trips.find(item => item.id === data.id);
    if (trip) trip.name = (data.name || trip.name || trip.id).trim();
}

if (action === "deleteTrip" && data.id !== 'default') {
    reg.ignored = [...new Set([...reg.ignored, data.id])];
    reg.trips = reg.trips.filter(item => item.id !== data.id);
    if (reg.active === data.id) reg.active = reg.trips[0].id;
}

if (action === "selectTrip") {
    const id = data.id;
    if (reg.trips.some(trip => trip.id === id)) reg.active = id;
}

persistContext();
writeMsg = { filename: REG_FILE, payload: JSON.stringify(reg, null, 2) };
fillUi();

if (["selectTrip", "createTrip", "deleteTrip"].includes(action)) uiMsg._needReload = true;

return [writeMsg, uiMsg];

